// [0x00424002] 
// Parameters infos:
// class AActor*                  ReturnValue                    ( CPF_Parm | CPF_OutParm | CPF_ReturnParm )
// class APawn*                   CheckPawn                      ( CPF_Parm )
// struct FVector                 TraceEnd                       ( CPF_Parm )
// struct FVector                 TraceStart                     ( CPF_OptionalParm | CPF_Parm )
// unsigned long                  bTraceActors                   ( CPF_OptionalParm | CPF_Parm )
// struct FVector                 Extent                         ( CPF_OptionalParm | CPF_Parm )
// int                            ExtraTraceFlags                ( CPF_OptionalParm | CPF_Parm )
// class AActor*                  HitActor                       ( CPF_Parm | CPF_OutParm )
// struct FVector                 HitLocation                    ( CPF_Parm | CPF_OutParm )
// struct FVector                 HitNormal                      ( CPF_Parm | CPF_OutParm )
// struct FTraceHitInfo           HitInfo                        ( CPF_OptionalParm | CPF_Parm | CPF_OutParm )

class AActor* ATGSVHUD::TraceActorEX ( class APawn* CheckPawn, struct FVector TraceEnd, struct FVector TraceStart, unsigned long bTraceActors, struct FVector Extent, int ExtraTraceFlags, class AActor** HitActor, struct FVector* HitLocation, struct FVector* HitNormal, struct FTraceHitInfo* HitInfo )
{
	static UFunction* pFnTraceActorEX = NULL;

	if ( ! pFnTraceActorEX )
		pFnTraceActorEX = (UFunction*) UObject::GObjObjects()->Data[ 206898 ];

	ATGSVHUD_execTraceActorEX_Parms TraceActorEX_Parms;
	TraceActorEX_Parms.CheckPawn = CheckPawn;
	memcpy ( &TraceActorEX_Parms.TraceEnd, &TraceEnd, 0xC );
	memcpy ( &TraceActorEX_Parms.TraceStart, &TraceStart, 0xC );
	TraceActorEX_Parms.bTraceActors = bTraceActors;
	memcpy ( &TraceActorEX_Parms.Extent, &Extent, 0xC );
	TraceActorEX_Parms.ExtraTraceFlags = ExtraTraceFlags;

	this->ProcessEvent ( pFnTraceActorEX, &TraceActorEX_Parms, NULL );

	if ( HitActor )
		*HitActor = TraceActorEX_Parms.HitActor;

	if ( HitLocation )
		memcpy ( HitLocation, &TraceActorEX_Parms.HitLocation, 0xC );

	if ( HitNormal )
		memcpy ( HitNormal, &TraceActorEX_Parms.HitNormal, 0xC );

	if ( HitInfo )
		memcpy ( HitInfo, &TraceActorEX_Parms.HitInfo, 0x20 );

	return TraceActorEX_Parms.ReturnValue;
};

